using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class WeatherTool
{
    [McpServerTool, Description("Gets the current weather for a given city.")]
    public static string GetWeather(
        [Description("The city name")] string city)
    {
        // Simulated weather data
        return $"The weather in {city} is 72°F and sunny.";
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        Uri = "config://app/settings",
        Name = "App Configuration",
        Description = "Returns the application configuration data.",
        MimeType = "application/json")]
    public static string GetAppConfig()
    {
        var config = new
        {
            Version = "1.0.0",
            Environment = "production",
            Features = new { DarkMode = true, Notifications = true },
            MaxRetries = 3
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/settings/{section}",
        Name = "App Configuration Section",
        Description = "Returns a specific section of configuration.",
        MimeType = "application/json")]
    public static string GetConfigSection(string section)
    {
        var sections = new Dictionary<string, object>
        {
            ["database"] = new { Host = "localhost", Port = 5432, Name = "appdb" },
            ["cache"] = new { Provider = "redis", Ttl = 300 },
            ["logging"] = new { Level = "Information", Format = "json" }
        };

        if (sections.TryGetValue(section.ToLowerInvariant(), out var data))
        {
            return JsonSerializer.Serialize(data, new JsonSerializerOptions { WriteIndented = true });
        }

        return JsonSerializer.Serialize(new { Error = $"Section '{section}' not found" });
    }
}

